package com.careerpilot.careerplan;
import com.careerpilot.modules.careerplan.dto.CareerPlanDtos.*;import com.careerpilot.modules.careerplan.service.*;import com.careerpilot.modules.careerplan.taxonomy.CareerSkillTaxonomy;import com.careerpilot.modules.jobmatch.scoring.SkillNormalizer;import com.careerpilot.modules.profile.entity.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class CareerPlanRulesTest{
 private final SkillNormalizer normalizer=new SkillNormalizer();private final CareerSkillTaxonomy taxonomy=new CareerSkillTaxonomy(normalizer);private final CareerSkillGapService gaps=new CareerSkillGapService(normalizer);
 @Test void taxonomyContainsExactlyTheEightM5Careers(){assertThat(taxonomy.supportedCareers()).containsExactly("Backend Developer","Frontend Developer","Data Analyst","Data Scientist","Cloud DevOps Engineer","Cybersecurity Analyst","QA Automation Engineer","Business Analyst");assertThat(taxonomy.find("backend developer")).isPresent();assertThat(taxonomy.find("Astronaut")).isEmpty();}
 @Test void normalizationAndGapDistinguishPresentMissingAndImprovement(){var java=skill("Java",ProficiencyLevel.BEGINNER);var spring=skill("springboot",ProficiencyLevel.INTERMEDIATE);var docker=skill("containers",ProficiencyLevel.ADVANCED);var result=gaps.analyze(taxonomy.find("Backend Developer").orElseThrow(),List.of(java,spring,docker));assertThat(result.present()).extracting(SkillGapItem::skill).contains("Spring Boot","Docker");assertThat(result.needsImprovement()).extracting(SkillGapItem::skill).containsExactly("Java");assertThat(result.missingCore()).extracting(SkillGapItem::skill).contains("REST APIs","PostgreSQL","Git");assertThat(result.score()).isBetween(1,99);}
 @Test void readinessRedistributesUnavailableEvidenceTransparently(){Profile profile=new Profile();profile.setProfileCompletionPercentage(80);var gap=new SkillGapResponse(50,List.of(),List.of(),List.of(),List.of());var result=new PlacementReadinessService().calculate(profile,gap,Optional.empty(),Optional.empty());assertThat(result.score()).isEqualTo(60);assertThat(result.components()).filteredOn(v->"UNAVAILABLE".equals(v.status())).hasSize(2).allSatisfy(v->assertThat(v.effectiveWeight()).isZero());assertThat(result.disclaimer()).contains("not a prediction");}
 private UserSkill skill(String name,ProficiencyLevel level){Skill skill=new Skill();skill.setDisplayName(name);skill.setNormalizedName(normalizer.normalize(name));UserSkill value=new UserSkill();value.setSkill(skill);value.setProficiencyLevel(level);return value;}
}

